-- THEAPP database setup. Replace YOUR_ADMIN_EMAIL before running.
create extension if not exists pgcrypto;
create table if not exists public.admin_users (email text primary key, created_at timestamptz not null default now());
insert into public.admin_users (email) values ('YOUR_ADMIN_EMAIL') on conflict (email) do nothing;
create or replace function public.is_admin() returns boolean language sql security definer set search_path=public stable as $$ select exists(select 1 from public.admin_users where lower(email)=lower(coalesce(auth.jwt()->>'email',''))); $$;
create table if not exists public.business_applications (id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users(id) on delete cascade, owner_email text, business_name text not null, category text not null, description text not null, how_made text, location text not null, website text, instagram text, certification_path text, portfolio_paths text[] not null default '{}', status text not null default 'pending' check(status in ('pending','needs_info','approved','rejected')), admin_note text, created_at timestamptz not null default now(), reviewed_at timestamptz);
create table if not exists public.business_profiles (id uuid primary key default gen_random_uuid(), application_id uuid unique references public.business_applications(id) on delete set null, owner_id uuid references auth.users(id) on delete set null, business_name text not null, category text not null, description text not null, how_made text, location text not null, latitude double precision, longitude double precision, website text, instagram text, certification_paths text[] not null default '{}', portfolio_paths text[] not null default '{}', products jsonb not null default '[]'::jsonb, services jsonb not null default '[]'::jsonb, verified boolean not null default true, created_at timestamptz not null default now());
alter table public.admin_users enable row level security; alter table public.business_applications enable row level security; alter table public.business_profiles enable row level security;
drop policy if exists "admin self read" on public.admin_users; create policy "admin self read" on public.admin_users for select to authenticated using(lower(email)=lower(coalesce(auth.jwt()->>'email','')));
drop policy if exists "owner insert application" on public.business_applications; create policy "owner insert application" on public.business_applications for insert to authenticated with check(owner_id=auth.uid());
drop policy if exists "owner or admin read application" on public.business_applications; create policy "owner or admin read application" on public.business_applications for select to authenticated using(owner_id=auth.uid() or public.is_admin());
drop policy if exists "admin update application" on public.business_applications; create policy "admin update application" on public.business_applications for update to authenticated using(public.is_admin()) with check(public.is_admin());
drop policy if exists "public read approved profiles" on public.business_profiles; create policy "public read approved profiles" on public.business_profiles for select using(verified=true);
drop policy if exists "admin insert profiles" on public.business_profiles; create policy "admin insert profiles" on public.business_profiles for insert to authenticated with check(public.is_admin());
drop policy if exists "admin update profiles" on public.business_profiles; create policy "admin update profiles" on public.business_profiles for update to authenticated using(public.is_admin()) with check(public.is_admin());
insert into storage.buckets(id,name,public) values('business-documents','business-documents',false) on conflict(id) do nothing;
drop policy if exists "owner upload docs" on storage.objects; create policy "owner upload docs" on storage.objects for insert to authenticated with check(bucket_id='business-documents' and (storage.foldername(name))[1]=auth.uid()::text);
drop policy if exists "owner or admin read docs" on storage.objects; create policy "owner or admin read docs" on storage.objects for select to authenticated using(bucket_id='business-documents' and ((storage.foldername(name))[1]=auth.uid()::text or public.is_admin()));
drop policy if exists "owner or admin update docs" on storage.objects; create policy "owner or admin update docs" on storage.objects for update to authenticated using(bucket_id='business-documents' and ((storage.foldername(name))[1]=auth.uid()::text or public.is_admin()));
drop policy if exists "owner or admin delete docs" on storage.objects; create policy "owner or admin delete docs" on storage.objects for delete to authenticated using(bucket_id='business-documents' and ((storage.foldername(name))[1]=auth.uid()::text or public.is_admin()));
